import itertools
from collections import deque

def check_graph(n, edges):
    # Build adjacency list
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check vertex connectivity >= 4
    # Try removing all subsets of size 0, 1, 2, 3 and see if graph stays connected
    def is_connected(removed):
        # BFS from first non-removed vertex
        start = None
        for i in range(n):
            if i not in removed:
                start = i
                break
        if start is None:
            return True  # All vertices removed, trivially "connected"

        visited = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            v = queue.popleft()
            for neighbor in adj[v]:
                if neighbor not in removed and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        # Check if all non-removed vertices are visited
        for i in range(n):
            if i not in removed and i not in visited:
                return False
        return True

    # Check connectivity by trying to remove up to 3 vertices
    for k in range(4):  # 0, 1, 2, 3
        for subset in itertools.combinations(range(n), k):
            if not is_connected(set(subset)):
                return False, f"Graph disconnected after removing {subset}"

    # Check maximum independent set size <= 3
    # Try all subsets of size 4 and verify none is independent
    for subset in itertools.combinations(range(n), 4):
        is_independent = True
        for i in range(len(subset)):
            for j in range(i+1, len(subset)):
                if subset[j] in adj[subset[i]]:
                    is_independent = False
                    break
            if not is_independent:
                break
        if is_independent:
            return False, f"Independent set of size 4 found: {subset}"

    return True, "All checks passed"

# Generate K_20
n = 20
edges = list(itertools.combinations(range(n), 2))
print(f"Number of edges: {len(edges)}")

result, msg = check_graph(n, edges)
print(f"Result: {result}, {msg}")
